// HDD capacity-speed index — record JAH-GPC-HDD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"capacity_tb": 4, "rpm": 5400};
var value = (m.capacity_tb*m.rpm/7200);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-HDD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-HDD-000001|' + value.toFixed(2) + ' capacity-speed index');

